namespace bench {

// bench/time.hpp: a reading of a node's clock, in nanoseconds since that clock's zero.
// Code in bench_core never reads a clock itself; the caller passes the reading in.
struct Time {
  std::chrono::nanoseconds since_epoch;
  auto operator<=>(const Time&) const = default;
};

// bench/replay.hpp from here on.

// One heartbeat as a monitor received it: one "value time_ns" line of its inputs file.
struct Received {
  std::int64_t value;
  Time time;  // the monitor's clock when the heartbeat arrived
};

// Both runs heard the same heartbeats, from first to last.
struct Same {
  std::int64_t first;
  std::int64_t last;
  std::int64_t count;
  std::chrono::nanoseconds live_span;    // first to last on the live monitor's clock
  std::chrono::nanoseconds replay_span;  // first to last on the replay monitor's clock
  std::chrono::nanoseconds offset;       // replay clock minus live clock at the first one
};

// The first heartbeat that one run heard and the other didn't.
struct Different {
  std::optional<std::int64_t> live;  // nothing when that run has no more heartbeats
  std::optional<std::int64_t> replay;
};

enum class Unusable { not_one_run, nothing_in_common };

using Comparison = std::variant<Same, Different, Unusable>;

// Parses an inputs file. Nothing if a line isn't two integers separated by one space.
[[nodiscard]] std::optional<std::vector<Received>> parse_received(std::string_view text) {
  std::vector<Received> received;
  for (const auto part : std::views::split(text, '\n')) {
    const std::string_view line(part.begin(), part.end());
    if (line.empty()) continue;
    const char* const end = line.data() + line.size();
    std::int64_t value = 0;
    std::int64_t nanoseconds = 0;
    const auto [after_value, value_error] = std::from_chars(line.data(), end, value);
    if (value_error != std::errc{} || after_value == end || *after_value != ' ') return std::nullopt;
    const auto [after_time, time_error] = std::from_chars(after_value + 1, end, nanoseconds);
    if (time_error != std::errc{} || after_time != end) return std::nullopt;
    received.push_back({.value = value, .time = {std::chrono::nanoseconds(nanoseconds)}});
  }
  return received;
}

// Reads and parses an inputs file. Nothing if it can't be opened or parsed.
[[nodiscard]] std::optional<std::vector<Received>> read_received(const std::filesystem::path& file) {
  std::ifstream in(file);
  if (!in) return std::nullopt;
  std::ostringstream text;
  text << in.rdbuf();
  return parse_received(text.str());
}

namespace {

// One run of one heartbeat: the values rise strictly, with no restart.
[[nodiscard]] bool one_run(std::span<const Received> run) {
  return std::ranges::adjacent_find(run, std::ranges::greater_equal{}, &Received::value) == run.end();
}

// The heartbeats of a run whose values lie in [first, last]. The run is sorted by value.
[[nodiscard]] std::span<const Received> stretch(std::span<const Received> run, std::int64_t first,
                                                std::int64_t last) {
  const auto begin = std::ranges::lower_bound(run, first, {}, &Received::value);
  const auto end = std::ranges::upper_bound(run, last, {}, &Received::value);
  return {begin, end};
}

[[nodiscard]] std::chrono::nanoseconds duration(std::span<const Received> run) {
  return run.back().time.since_epoch - run.front().time.since_epoch;
}

[[nodiscard]] double seconds(std::chrono::nanoseconds d) { return std::chrono::duration<double>(d).count(); }

[[nodiscard]] std::string value_or_nothing(std::optional<std::int64_t> value) {
  return value ? std::to_string(*value) : "nothing";
}

struct Describe {
  std::string operator()(const Same& same) const {
    return std::format("same: {} heartbeats, {} to {}; {:.2f} s live, {:.2f} s replay; replay clock {:+.2f} s",
                       same.count, same.first, same.last, seconds(same.live_span), seconds(same.replay_span),
                       seconds(same.offset));
  }
  std::string operator()(const Different& different) const {
    return std::format("different: live has {}, replay has {}", value_or_nothing(different.live),
                       value_or_nothing(different.replay));
  }
  std::string operator()(Unusable unusable) const {
    return unusable == Unusable::not_one_run ? "can't compare: a run restarted"
                                             : "can't compare: no heartbeat in common";
  }
};

}  // namespace

// Compares two runs over the heartbeats both could have heard: from the later first value to
// the earlier last one, because each run may miss a few at its start while discovery runs.
[[nodiscard]] Comparison compare_runs(std::span<const Received> live, std::span<const Received> replay) {
  if (!one_run(live) || !one_run(replay)) return Unusable::not_one_run;
  if (live.empty() || replay.empty()) return Unusable::nothing_in_common;
  const std::int64_t first = std::max(live.front().value, replay.front().value);
  const std::int64_t last = std::min(live.back().value, replay.back().value);
  if (first > last) return Unusable::nothing_in_common;

  const auto live_part = stretch(live, first, last);
  const auto replay_part = stretch(replay, first, last);
  const auto [live_it, replay_it] =
      std::ranges::mismatch(live_part, replay_part, {}, &Received::value, &Received::value);
  if (live_it != live_part.end() || replay_it != replay_part.end()) {
    const auto value_at = [](auto it, auto end) -> std::optional<std::int64_t> {
      if (it == end) return std::nullopt;
      return it->value;
    };
    return Different{.live = value_at(live_it, live_part.end()), .replay = value_at(replay_it, replay_part.end())};
  }
  return Same{.first = first,
              .last = last,
              .count = std::ssize(live_part),
              .live_span = duration(live_part),
              .replay_span = duration(replay_part),
              .offset = replay_part.front().time.since_epoch - live_part.front().time.since_epoch};
}

// One line for a person to read.
[[nodiscard]] std::string describe(const Comparison& comparison) { return std::visit(Describe{}, comparison); }

}  // namespace bench

int main() {
  // The live monitor missed heartbeats 0 and 1. The bag starts at 1, and the replay on the
  // recording's clock reads each arrival 10 ms early.
  const auto live = bench::parse_received("2 5200000000\n3 5300000000\n4 5400000000\n5 5500000000\n");
  const auto replay = bench::parse_received("1 5090000000\n2 5190000000\n3 5290000000\n4 5390000000\n5 5490000000\n");
  const auto lost_one = bench::parse_received("2 5190000000\n3 5290000000\n5 5490000000\n");
  const auto restarted = bench::parse_received("7 5000000000\n0 5100000000\n");
  if (!live || !replay || !lost_one || !restarted) return 1;

  std::cout << bench::describe(bench::compare_runs(*live, *replay)) << '\n';
  std::cout << bench::describe(bench::compare_runs(*live, *lost_one)) << '\n';
  std::cout << bench::describe(bench::compare_runs(*live, *restarted)) << '\n';
  std::cout << std::format("\"2 5x\" parses: {}\n", bench::parse_received("2 5x\n").has_value());
  std::cout << std::format("a missing file reads: {}\n", bench::read_received("/no/such/inputs.txt").has_value());
}

#include <variant>

#include <gtest/gtest.h>

#include "bench/replay.hpp"

TEST(CompareRuns, SkipsTheHeartbeatsOneRunMissedAtItsStart) {
  const auto live = bench::parse_received("2 200\n3 300\n4 400\n");
  const auto replay = bench::parse_received("1 100\n2 200\n3 300\n4 400\n");
  ASSERT_TRUE(live && replay);
  const bench::Comparison comparison = bench::compare_runs(*live, *replay);
  ASSERT_TRUE(std::holds_alternative<bench::Same>(comparison));
  EXPECT_EQ(std::get<bench::Same>(comparison).count, 3);
}

#include <iostream>
#include <variant>

#include "bench/replay.hpp"

// compare_runs LIVE_FILE REPLAY_FILE: exit code 0 when both runs heard the same heartbeats.
int main(int argc, char** argv) {
  if (argc != 3) { std::cerr << "usage: compare_runs LIVE_FILE REPLAY_FILE\n"; return 2; }
  const auto live = bench::read_received(argv[1]);
  const auto replay = bench::read_received(argv[2]);
  if (!live || !replay) { std::cerr << "can't read or parse an inputs file\n"; return 2; }
  const bench::Comparison comparison = bench::compare_runs(*live, *replay);
  std::cout << bench::describe(comparison) << '\n';
  return std::holds_alternative<bench::Same>(comparison) ? 0 : 1;
}
